<template>
  <section class="min-w-0 space-y-4 text-sm" data-testid="typed-table-retention">
    <UAlert color="info" variant="soft" :title="t('storageGov.tableRetention.title')" :description="t(id === 'capability_registry_discovery_cache' ? 'storageGov.tableRetention.cacheRule' : 'storageGov.tableRetention.probeRule')" />
    <UAlert v-if="error || readError" color="error" :title="t('storageGov.loadFailed')" :description="error || readError" />
    <div v-if="unknown" class="space-y-2" data-testid="system-retention-unknown"><UAlert color="warning" :title="t('storageGov.dbControl.unknown')" :description="t('storageGov.dbControl.unknownHint')" /><p class="break-all text-xs text-muted">{{ unknown.key }}</p><div class="flex flex-wrap gap-2"><UButton :loading="busy" data-testid="system-retention-reconcile" @click="reconcile">{{ t('storageGov.tableMonitor.control.reconcile') }}</UButton><UButton color="neutral" variant="outline" @click="section = unknown.kind === 'policy' ? 'settings' : 'preview'">{{ t('storageGov.systemControl.returnTask') }}</UButton></div></div>
    <template v-if="status">
      <div class="space-y-2 rounded-lg border border-default p-3"><p class="font-medium">{{ t(status.policy.enabled && configuration?.execution_ready && status.worker_enabled && status.enforcement_allowed ? 'storageGov.runtime.enabled' : 'storageGov.runtime.disabled') }} · {{ t('storageGov.systemControl.summary',{days:status.policy.retention_days,limit:status.policy.batch_limit}) }}</p><p v-if="configuration" class="text-xs text-muted" data-testid="system-retention-versions">{{ t('storageGov.dbControl.versions', {desired:configuration.desired_revision,applied:configuration.applied_revision,snapshot:configuration.snapshot_revision ?? '—'}) }}</p><p v-if="status.problem || status.adapter_problem" class="text-warning">{{ problem(status.problem || status.adapter_problem || '') }}</p><UButton color="neutral" variant="outline" size="xs" :loading="loading" @click="load()">{{ t('storageGov.refresh') }}</UButton></div>
      <BackupSectionTabs v-model="section" :items="sections" :label="t('storageGov.tableRetention.title')">
        <template #settings><div class="space-y-4" data-testid="system-retention-settings">
          <template v-if="configuration?.authority === 'legacy'"><p class="text-muted">{{ t('storageGov.systemControl.adoption') }}</p><UCheckbox :model-value="adoptionConfirmed" :disabled="blocked" @update:model-value="confirmAdoption" :label="t('storageGov.systemControl.confirmAdopt')" data-testid="system-retention-adopt-confirm" /><UButton :disabled="blocked || !configuration.ready || !adoptionConfirmed || !!status.unconfirmed_runs" data-testid="system-retention-adopt" @click="adopt">{{ t('storageGov.systemControl.adopt') }}</UButton></template>
          <template v-else-if="configuration?.authority === 'database'">
            <UForm :id="formID" :state="draft" :schema="schema" class="space-y-3" @submit="save"><p class="text-xs text-muted">{{ t('storageGov.systemControl.draftVersion',{revision:draftRevision}) }}</p><div class="grid gap-3 lg:grid-cols-2"><UFormField name="retention_days" :label="t('storageGov.tableRetention.days')"><UInput v-model.number="draft.retention_days" type="number" min="7" max="3650" class="w-full" :disabled="blocked || !configuration.ready" data-testid="system-retention-days" @update:model-value="dirty = true" /></UFormField><UFormField name="batch_limit" :label="t('storageGov.tableRetention.batch')"><UInput v-model.number="draft.batch_limit" type="number" min="1" max="500" class="w-full" :disabled="blocked || !configuration.ready" data-testid="system-retention-batch" @update:model-value="dirty = true" /></UFormField></div><p class="text-xs text-muted">{{ t('storageGov.systemControl.savePaused') }}</p><div class="flex flex-wrap gap-2"><UButton type="submit" :disabled="blocked || !dirty || !configuration.ready" :loading="busy" data-testid="system-retention-save">{{ t('storageGov.systemControl.save') }}</UButton><UButton type="button" color="neutral" variant="ghost" :disabled="blocked" data-testid="system-retention-latest" @click="loadLatest">{{ t('storageGov.tableMonitor.control.loadLatest') }}</UButton></div></UForm>
            <div class="space-y-2 border-t border-default pt-3"><UCheckbox :model-value="toggleConfirmed" :disabled="blocked || dirty || !configuration.ready" :label="t('storageGov.systemControl.confirmToggle')" data-testid="system-retention-toggle-confirm" @update:model-value="confirmToggle" /><UButton color="neutral" variant="outline" :disabled="blocked || dirty || !toggleConfirmed || !configuration.ready || (!toggleEnabled && !status.policy.enabled) || (toggleEnabled && !status.ready)" data-testid="system-retention-toggle" @click="toggle">{{ t((toggleConfirmed ? toggleEnabled : !status.policy.enabled) ? 'storageGov.dbControl.enable' : 'storageGov.dbControl.pause') }}</UButton></div>
          </template><p v-else class="text-warning">{{ t('storageGov.systemControl.unavailable') }}</p>
        </div></template>
        <template #preview><div class="space-y-3" data-testid="system-retention-preview-panel"><p class="text-muted">{{ t('storageGov.dbControl.previewHint') }}</p><UButton color="neutral" variant="outline" :disabled="blocked || dirty || !status.ready" :loading="busy" data-testid="system-retention-preview" @click="previewBatch">{{ t('storageGov.tableRetention.preview') }}</UButton><template v-if="preview"><p data-testid="typed-cleanup-preview">{{ t('storageGov.tableRetention.matched',{count:preview.rows}) }} · {{ t('storageGov.tableRetention.cutoff') }} {{ date(preview.cutoff) }}</p><UCheckbox v-model="executionConfirmed" :disabled="blocked" :label="t('storageGov.tableRetention.confirm')" data-testid="system-retention-execute-confirm" /><UButton color="error" :disabled="blocked || dirty || !executionConfirmed || !status.policy.enabled || !configuration?.execution_ready || preview.revision !== status.revision" data-testid="system-retention-execute" @click="execute">{{ t('storageGov.tableRetention.execute') }}</UButton></template></div></template>
        <template #runs><div class="space-y-3" data-testid="system-retention-runs"><p v-if="!status.runs.length" class="text-muted">{{ t('storageGov.systemControl.noRuns') }}</p><ol class="max-h-96 space-y-3 overflow-auto"><li v-for="r in status.runs" :key="r.id" class="rounded-lg border border-default p-3"><p>{{ date(r.at) }} · {{ t(`storageGov.tableRetention.states.${r.state}`) }} · v{{ r.revision }}</p><p>{{ t('storageGov.tableRetention.resultRows',{count:r.rows}) }} · {{ t('storageGov.dbControl.'+(r.trigger === 'scheduled' ? 'scheduled' : r.trigger === 'manual' ? 'manual' : 'historical')) }}</p><details class="mt-2 text-xs text-muted"><summary>{{ t('storageGov.dbControl.receipt') }}</summary><p class="break-all">{{ r.id }}</p></details></li></ol></div></template>
      </BackupSectionTabs>
    </template>
  </section>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, useId, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import * as v from 'valibot';
import BackupSectionTabs from '~/components/ops/backup/BackupSectionTabs.vue';
import { useStorageDatabaseTablesService, type SystemTableRetentionMutation, type SystemTableRetentionRun, type SystemTableRetentionStatus } from '~/composables/api/services/storageDatabaseTablesService';
const props = defineProps<{ id: string; revision?: number }>();
const emit = defineEmits<{ uncertain: [value: boolean]; saved: [status: SystemTableRetentionStatus] }>();
const {t,te,locale}=useI18n(),api=useStorageDatabaseTablesService(),formID='system-retention-'+useId();
const status=ref<SystemTableRetentionStatus>(),configuration=computed(()=>status.value?.configuration),section=ref('settings'),draft=reactive({retention_days:30,batch_limit:200}),draftRevision=ref(0),dirty=ref(false),busy=ref(false),loading=ref(false),readError=ref(''),error=ref(''),preview=ref<SystemTableRetentionRun>(),executionConfirmed=ref(false),adoptionConfirmed=ref(false),toggleConfirmed=ref(false),toggleEnabled=ref(false);
type Operation={kind:'policy'|'run';key:string;revision:number;id:string};
const unknown=ref<Operation>(),blocked=computed(()=>busy.value||!!unknown.value),sections=computed(()=>[{value:'settings',label:t('storageGov.systemControl.settings')},{value:'preview',label:t('storageGov.systemControl.preview')},{value:'runs',label:t('storageGov.tableRetention.runs')}]);
const integer=(min:number,max:number)=>v.pipe(v.number(),v.integer(),v.minValue(min),v.maxValue(max)),schema=v.object({retention_days:integer(7,3650),batch_limit:integer(1,500)});
let disposed=false,initialized=false,read:AbortController|undefined,write:AbortController|undefined,toggleRevision=0,requestID='',adoptionDigest='';
const date=(value:string)=>new Intl.DateTimeFormat(locale.value,{dateStyle:'short',timeStyle:'short'}).format(new Date(value));
function problem(code:string){const key='storageGov.tableRetention.problems.'+code;return te(key)?t(key):code;}
function fill(){if(!status.value)return;draft.retention_days=status.value.policy.retention_days;draft.batch_limit=status.value.policy.batch_limit;draftRevision.value=status.value.revision;dirty.value=false;initialized=true;toggleConfirmed.value=false;}
async function load(reset=false){read?.abort();const c=read=new AbortController();loading.value=true;try{const value=await api.retention(c.signal,props.id);if(disposed||c.signal.aborted)return;status.value=value;if(reset||!initialized)fill();readError.value='';if(reset)error.value='';emit('saved',value);}catch(e:any){if(!disposed&&!c.signal.aborted)readError.value=e?.message||String(e);}finally{if(!disposed&&!c.signal.aborted)loading.value=false;}}
async function loadLatest(){if(blocked.value)return;await load(true);}
async function accept(m:SystemTableRetentionMutation,op:Operation){if(m.table_id!==op.id||m.request_id!==op.key||m.operation_revision!==op.revision+1)throw new Error('SYSTEM_RETENTION_RECEIPT_INVALID');unknown.value=undefined;adoptionConfirmed.value=false;toggleConfirmed.value=false;dirty.value=false;initialized=false;preview.value=undefined;await load();}
async function mutate(op:Operation,call:(signal:AbortSignal)=>Promise<SystemTableRetentionMutation|SystemTableRetentionRun>){if(blocked.value)return;const c=write=new AbortController();busy.value=true;error.value='';try{const out=await call(c.signal);if(disposed||c.signal.aborted)return;if(op.kind==='policy')await accept(out as SystemTableRetentionMutation,op);else{const r=out as SystemTableRetentionRun;if(r.id!==op.key||r.table_id!==op.id||r.revision!==op.revision||r.state!=='completed')throw new Error('SYSTEM_RETENTION_RECEIPT_INVALID');unknown.value=undefined;preview.value=undefined;executionConfirmed.value=false;section.value='runs';await load();}}catch(e:any){if(!disposed&&!c.signal.aborted){error.value=e?.message||String(e);const status=e?.status||e?.statusCode||e?.response?.status;if(![400,401,403,409,422,428].includes(status))unknown.value=op;}}finally{if(!disposed)busy.value=false;}}
function confirmAdoption(value:boolean|'indeterminate'){adoptionConfirmed.value=value===true;if(adoptionConfirmed.value)adoptionDigest=configuration.value?.legacy_digest||'';}
async function adopt(){if(!adoptionConfirmed.value||!configuration.value)return;const op:Operation={kind:'policy',key:crypto.randomUUID(),id:props.id,revision:0},hash=adoptionDigest;await mutate(op,signal=>api.adoptRetention(signal,op.id,{request_id:op.key,legacy_digest:hash,confirm:true}));}
async function save(){if(!dirty.value||!v.safeParse(schema,draft).success)return;const op:Operation={kind:'policy',key:crypto.randomUUID(),id:props.id,revision:draftRevision.value},settings={...draft};await mutate(op,signal=>api.changeRetention(signal,op.id,{request_id:op.key,expected_revision:op.revision,action:'save',settings,confirm:true}));}
function confirmToggle(value:boolean|'indeterminate'){toggleConfirmed.value=value===true;if(toggleConfirmed.value&&status.value){toggleRevision=status.value.revision;toggleEnabled.value=!status.value.policy.enabled;}}
async function toggle(){if(!toggleConfirmed.value)return;const op:Operation={kind:'policy',key:crypto.randomUUID(),id:props.id,revision:toggleRevision},enabled=toggleEnabled.value;await mutate(op,signal=>api.changeRetention(signal,op.id,{request_id:op.key,expected_revision:op.revision,action:'status',enabled,confirm:true}));}
async function previewBatch(){if(!status.value||blocked.value)return;const c=write=new AbortController();busy.value=true;error.value='';try{const p=await api.previewRetention(c.signal,props.id,status.value.revision);if(disposed||c.signal.aborted)return;preview.value=p;executionConfirmed.value=false;requestID=crypto.randomUUID();}catch(e:any){if(!disposed&&!c.signal.aborted)error.value=e?.message||String(e);}finally{if(!disposed)busy.value=false;}}
async function execute(){if(!preview.value||!executionConfirmed.value)return;const p=preview.value,op:Operation={kind:'run',key:requestID,id:props.id,revision:p.revision};await mutate(op,signal=>api.runRetention(signal,op.id,p,op.key));}
async function reconcile(){const op=unknown.value;if(!op||busy.value)return;const c=write=new AbortController();busy.value=true;error.value='';try{if(op.kind==='policy')await accept(await api.retentionRequest(c.signal,op.id,op.key),op);else{const r=await api.retentionRunRequest(c.signal,op.id,op.key);if(r.id!==op.key||r.table_id!==op.id||r.revision!==op.revision||r.state!=='completed')throw new Error('SYSTEM_RETENTION_RECEIPT_INVALID');unknown.value=undefined;preview.value=undefined;section.value='runs';await load();}}catch{if(!disposed&&!c.signal.aborted)error.value=t('storageGov.dbControl.unknownHint');}finally{if(!disposed)busy.value=false;}}
watch(()=>busy.value||!!unknown.value,value=>emit('uncertain',value));watch(()=>props.revision,()=>load());onMounted(()=>load());onBeforeUnmount(()=>{disposed=true;read?.abort();write?.abort();});
</script>
